const test=require('node:test'),assert=require('node:assert/strict'),fs=require('fs'),vm=require('vm');
const ctx={console,TextEncoder,TextDecoder,btoa:s=>Buffer.from(s,'binary').toString('base64'),atob:s=>Buffer.from(s,'base64').toString('binary'),crypto:require('crypto').webcrypto};ctx.globalThis=ctx;ctx.window=ctx;vm.createContext(ctx);
for(const f of ['data.js','clinical-model-v2.js','clinical-addons.js','clinical-library-v3.js','exercise-intelligence-knee.js','exercise-intelligence-next.js','core.js','planner.js'])vm.runInContext(fs.readFileSync('reda-2/'+f,'utf8'),ctx);
const P=ctx.RedaPlanner,C=ctx.RedaClinical,D=ctx.RedaData;
test('intelligence library contains real higher-capacity options',()=>{for(const id of ['leg_press','knee_extension_machine','spanish_squat','rear_foot_split_squat','single_leg_squat_box','pogos','cable_er','landmine_press','standing_calf_loaded','seated_calf_loaded','hip_thrust'])assert.ok(D.exercises.some(x=>x.id===id),id)});
test('patient who already did basic rehab gets a deeper knee plan when clinician selects that context',()=>{const p=P.buildProgram({blueprintId:'knee_pf',stage:'build',capacity:'standard',trainingHistory:'rehab_experienced',goalProfile:'strength',equipment:'gym',floorOK:true,band:true});assert.equal(p.intelligenceTier,'advanced');assert.ok(p.exercises.some(x=>['leg_press','knee_extension_machine','rear_foot_split_squat','single_leg_squat_box'].includes(x.id)));assert.ok(p.exercises.every(x=>x.why&&x.challenge));});
test('protected phase does not jump to advanced plan merely because patient is experienced',()=>{const p=P.buildProgram({blueprintId:'knee_pf',stage:'protected',capacity:'standard',trainingHistory:'rehab_experienced',goalProfile:'strength',equipment:'gym',floorOK:true,band:true});assert.equal(p.intelligenceTier,'foundation');});
test('performance tier requires explicit clinician-selected high capacity, high load and sport goal',()=>{const p=P.buildProgram({blueprintId:'knee_pf',stage:'higher',capacity:'high',trainingHistory:'rehab_experienced',goalProfile:'sport',equipment:'gym',floorOK:true,band:true});assert.equal(p.intelligenceTier,'performance');assert.ok(p.exercises.some(x=>x.id==='pogos'));});
test('impact exercise is not selected outside sport profile',()=>{const p=P.buildProgram({blueprintId:'knee_pf',stage:'higher',capacity:'high',trainingHistory:'rehab_experienced',goalProfile:'strength',equipment:'gym',floorOK:true,band:true});assert.equal(p.exercises.some(x=>x.id==='pogos'),false);});
test('experienced shoulder plan can move beyond band-only rehab',()=>{const p=P.buildProgram({blueprintId:'shoulder_load',stage:'build',capacity:'standard',trainingHistory:'rehab_experienced',goalProfile:'strength',equipment:'gym',floorOK:true,band:true});assert.equal(p.intelligenceTier,'advanced');assert.ok(p.exercises.some(x=>['cable_er','landmine_press'].includes(x.id)));});
test('experienced Achilles plan can use measurable external load',()=>{const p=P.buildProgram({blueprintId:'achilles',stage:'build',capacity:'standard',trainingHistory:'rehab_experienced',goalProfile:'strength',equipment:'gym',floorOK:true,band:true});assert.equal(p.intelligenceTier,'advanced');assert.ok(p.exercises.some(x=>['standing_calf_loaded','seated_calf_loaded'].includes(x.id)));});
test('experienced lateral hip plan can move beyond clamshells',()=>{const p=P.buildProgram({blueprintId:'hip_gtps',stage:'build',capacity:'standard',trainingHistory:'rehab_experienced',goalProfile:'strength',equipment:'gym',floorOK:true,band:true});assert.equal(p.intelligenceTier,'advanced');assert.ok(p.exercises.some(x=>x.id==='hip_thrust'));});
test('progression remains clinician only',()=>assert.equal(C.progression.rule,'clinician_only'));
test('Hyrox requires selected high capacity and stage; the goal alone never unlocks impact',()=>{const base={blueprintId:'knee_pf',trainingHistory:'rehab_experienced',goalProfile:'hyrox',equipment:'gym',floorOK:true,band:true};assert.equal(P.buildProgram({...base,capacity:'high',stage:'higher'}).intelligenceTier,'performance');assert.equal(P.buildProgram({...base,capacity:'high',stage:'protected'}).intelligenceTier,'foundation');assert.notEqual(P.buildProgram({...base,capacity:'standard',stage:'build'}).intelligenceTier,'performance');});
